import type { Rarity } from '@/lib/content'

/**
 * Lab of Horrors Locksmith: decipher + trade facts, shared by the dungeon, dungeon-items, tags and crates
 * wiki pages so a retune means one edit here. Not a wiki page itself (index.ts does not list it).
 *
 * Sources (read-only, 2026-11-25, re-read 09:30):
 * - <srv>/plugins/DeluxeMenus/gui_menus/DUNGEON/Locksmith.yml, menu title "Locksmith | Keys, Decipher & Trade"
 *   (file 08:58, generated by /root/launch/work/gameplay3/gen_locksmith.py). Buttons DECIPHER_COMMON/RARE/LEGENDARY/
 *   FABLED(_OWNED) and TRADE_HEXTECH/WARDEN/CRYSTAL/CRYSTAL_TAG: `minecraft:clear` counts first, then removes and
 *   rewards only if every count passed. Rewards: `mm items give` books, `crate key give <p> epic|spawner`,
 *   `lp user <p> permission set kasadya.tag.hextech true`. Nothing pays money.
 * - <srv>/plugins/MythicMobs/items/LabOfHorrors/loh_rewards.yml: the books are vanilla ENCHANTED_BOOKs with stored
 *   enchantments, so they work in an anvil like any other book.
 * - <srv>/plugins/AlonsoTags/tags.yml `hextech`: Permission kasadya.tag.hextech, Price 0 (cannot be bought). 14 tags total.
 * - /root/launch/CHANGELOG.md, GAMEPLAY FIXER round 3, BLOCKER 2 (rates 8 / 4 / 1 / 3, live-tested).
 * The owner can retune the rates in gen_locksmith.py: re-read Locksmith.yml before every release.
 */

/** How the tag is written on the site (small caps [ʜᴇxᴛᴇᴄʜ] in game). */
export const HEXTECH_TAG = '[HEXTECH]'

export const LOCKSMITH = {
  /** TRADE_HEXTECH: clear RAW_HEXTECH 8 -> crate key give epic 1 */
  rawHextechPerEpicKey: 8,
  /** TRADE_WARDEN: clear WARDEN_INGOT 4 -> crate key give spawner 1 */
  wardenIngotsPerSpawnerKey: 4,
  /** TRADE_CRYSTAL: clear HEXTECH_CRYSTAL 1 -> crate key give spawner 2 */
  spawnerKeysPerCrystal: 2,
  /** TRADE_CRYSTAL_TAG: clear HEXTECH_CRYSTAL 3 -> kasadya.tag.hextech (hidden once you own it) */
  crystalsForTag: 3,
} as const

export interface DecipherRow {
  book: string
  rarity: Rarity
  gives: string
}

